class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = monthly_limit_mib * 1024 * 1024
        self._usage: dict[str, int] = {}
        self._files: dict[str, int] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes <= 0:
            raise ValueError("File size must be positive")

        new_usage = self._usage.get(month, 0) + size_bytes
        if new_usage > self._limit_bytes:
            raise ValueError("Monthly upload quota exceeded")

        self._usage[month] = new_usage
        self._files[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        self._files.pop(name, None)

    def used_bytes(self, month: str) -> int:
        return self._usage.get(month, 0)
